import { useState } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { HttpError, postJson } from '../../api/http';
import { useSingleFlight } from '../../query/useSingleFlight';
import { SheetBody } from '../../slots/defs/sheetBody';
import { PersonCells, PersonColumnHead, PersonDetail } from '../../slots/defs/personRow';
import { claimsKey, type Claim } from '../claims/useClaims';
import { useShowRetired } from '../retire/useShowRetired';
import { GRADES, fetchPeople, peopleKey, usePeople, type Person } from './usePeople';

/** The sheet's people: a form that adds a person, or edits one when their editor is open, and the
 *  list of everyone in the order they were added (retired people only when "show retired" is on), each
 *  with the grade in force on the sheet's today. An edit records the form's grade from its from-date
 *  (blank: the sheet's today); the first grade a person is given applies from the beginning of time.
 *  The editor remembers the version of the person it loaded; when someone else has saved them since,
 *  the save is refused (409) and the editor shows their current values, at their current version. Each person is a <tbody> so features can add
 *  cells and rows of their own to it (slots/defs/personRow). A quick-add bar takes a name and an amount
 *  and adds a draft claim for that person (adding them with grade A when the name is new) in one change. */
function People({ sheetId }: { sheetId: string }) {
  const people = usePeople(sheetId);
  const [showRetired] = useShowRetired();
  const queryClient = useQueryClient();
  const [editing, setEditing] = useState<number | null>(null);
  const [name, setName] = useState('');
  const [grade, setGrade] = useState<string>('A');
  const [gradeFrom, setGradeFrom] = useState('');
  const [version, setVersion] = useState<number | null>(null);

  const submitOnce = useSingleFlight();
  const save = useMutation({
    mutationFn: (f: { id: number | null; name: string; grade: string; gradeFrom: string; version: number | null }) => {
      const base = `/api/sheets/${encodeURIComponent(sheetId)}/people`;
      return f.id === null
        ? postJson<Person>(base, { name: f.name, grade: f.grade })
        : postJson<Person>(`${base}/${f.id}`, { name: f.name, grade: f.grade, gradeFrom: f.gradeFrom, version: f.version });
    },
    onSuccess: async () => {
      setEditing(null);
      setName('');
      setGrade('A');
      setGradeFrom('');
      setVersion(null);
      await queryClient.invalidateQueries({ queryKey: peopleKey(sheetId) });
    },
    onError: async (err, f) => {
      if (!(err instanceof HttpError && err.status === 409) || f.id === null) return;
      const people = await queryClient.fetchQuery({
        queryKey: peopleKey(sheetId),
        queryFn: () => fetchPeople(sheetId),
        staleTime: 0,
      });
      const current = people.find((p) => p.id === f.id);
      if (current) {
        setName(current.name);
        setGrade(current.grade);
        setVersion(current.version);
      }
    },
  });

  const [quickName, setQuickName] = useState('');
  const [quickAmount, setQuickAmount] = useState('');
  const quickOnce = useSingleFlight();
  const quick = useMutation({
    mutationFn: (f: { name: string; amount: string }) =>
      postJson<Claim>(`/api/sheets/${encodeURIComponent(sheetId)}/quick`, f),
    onSuccess: async () => {
      setQuickName('');
      setQuickAmount('');
      await Promise.all([
        queryClient.invalidateQueries({ queryKey: peopleKey(sheetId) }),
        queryClient.invalidateQueries({ queryKey: claimsKey(sheetId) }),
      ]);
    },
  });

  const openEditor = (p: Person) => {
    save.reset();
    setEditing(p.id);
    setName(p.name);
    setGrade(p.grade);
    setGradeFrom('');
    setVersion(p.version);
  };

  const cancel = () => {
    save.reset();
    setEditing(null);
    setName('');
    setGrade('A');
    setGradeFrom('');
    setVersion(null);
  };

  return (
    <section data-testid="people">
      <form
        data-testid="person-form"
        onSubmit={(e) => {
          e.preventDefault();
          submitOnce(() => {
            save.reset();
            return save.mutateAsync({ id: editing, name, grade, gradeFrom, version });
          });
        }}
      >
        <label>
          Name{' '}
          <input
            data-testid="person-form-name"
            value={name}
            onChange={(e) => {
              setName(e.target.value);
              save.reset();
            }}
          />
        </label>{' '}
        <label>
          Grade{' '}
          <select
            data-testid="person-form-grade"
            value={grade}
            onChange={(e) => {
              setGrade(e.target.value);
              save.reset();
            }}
          >
            {GRADES.map((g) => (
              <option key={g} value={g}>
                {g}
              </option>
            ))}
          </select>
        </label>{' '}
        <label>
          from{' '}
          <input
            type="date"
            data-testid="person-form-grade-from"
            value={gradeFrom}
            onChange={(e) => {
              setGradeFrom(e.target.value);
              save.reset();
            }}
          />
        </label>{' '}
        <button type="submit" data-testid="person-form-submit" disabled={save.isPending}>
          {editing === null ? 'Add person' : 'Save person'}
        </button>
        {editing !== null && (
          <>
            {' '}
            <button type="button" data-testid="person-form-cancel" onClick={cancel}>
              Cancel
            </button>
          </>
        )}
        {save.isError && <p data-testid="person-form-error">{save.error.message}</p>}
      </form>
      <form
        data-testid="quick-add"
        onSubmit={(e) => {
          e.preventDefault();
          quickOnce(() => {
            quick.reset();
            return quick.mutateAsync({ name: quickName, amount: quickAmount });
          });
        }}
      >
        <label>
          Quick add: name{' '}
          <input
            data-testid="quick-name"
            value={quickName}
            onChange={(e) => {
              setQuickName(e.target.value);
              quick.reset();
            }}
          />
        </label>{' '}
        <label>
          Amount{' '}
          <input
            data-testid="quick-amount"
            value={quickAmount}
            onChange={(e) => {
              setQuickAmount(e.target.value);
              quick.reset();
            }}
          />
        </label>{' '}
        <button type="submit" data-testid="quick-submit" disabled={quick.isPending}>
          Add draft claim
        </button>
        {quick.isError && <p data-testid="quick-error">{quick.error.message}</p>}
      </form>
      <table data-testid="people-list">
        <thead>
          <tr>
            <th>Name</th>
            <th>Grade</th>
            <PersonColumnHead.Slot sheetId={sheetId} />
            <th />
          </tr>
        </thead>
        {(people.data ?? []).filter((p) => showRetired || !p.retiredFrom).map((p) => (
          <tbody key={p.id} data-testid={`person-row-${p.id}`}>
            <tr>
              <td data-testid="person-name">{p.name}</td>
              <td data-testid="person-grade">{p.grade}</td>
              <PersonCells.Slot sheetId={sheetId} personId={p.id} />
              <td>
                <button type="button" data-testid={`person-edit-${p.id}`} onClick={() => openEditor(p)}>
                  Edit
                </button>
              </td>
            </tr>
            <PersonDetail.Slot sheetId={sheetId} personId={p.id} />
          </tbody>
        ))}
      </table>
      {people.isError && <p data-testid="people-error">{people.error.message}</p>}
    </section>
  );
}

export const contribution = SheetBody.fill({
  order: 10,
  Component: ({ sheetId }) => <People sheetId={sheetId} />,
});
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';

/** A person: `grade` is the one in force on the sheet's today, `grades` every grade they have been
 *  given, oldest first; `version` goes up by one each time they are saved. Their statements: how many have been
 *  taken, and the last one's due-total and date (null before the first); the date they are retired
 *  from (null when not retired); whether they are on hold (their OPEN claims then count in no live
 *  total). */
export type Person = {
  id: number;
  name: string;
  grade: string;
  grades: GradeFrom[];
  version: number;
  statementCount: number;
  statedTotal: string | null;
  statementDate: string | null;
  retiredFrom: string | null;
  held: boolean;
};

/** One of a person's grades: in force from its from-date (yyyy-mm-dd; null for the first grade they
 *  were given, which applies from the beginning of time) until the next one's. */
export type GradeFrom = { grade: string; from: string | null };

/** The grade a person has on a date (yyyy-mm-dd): the one with the latest from-date on or before it. */
export function gradeOn(person: Person | undefined, on: string): string | undefined {
  let found: GradeFrom | undefined;
  for (const g of person?.grades ?? []) {
    if (g.from !== null && g.from > on) continue;
    if (found === undefined || (found.from ?? '') < (g.from ?? '')) found = g;
  }
  return found?.grade;
}

/** One of a person's patrons: another person on the same sheet, by id. */
export type Patron = { personId: number; patronId: number };

export const GRADES = ['A', 'B', 'C'] as const;

export function peopleKey(sheetId: string) {
  return ['sheet', sheetId, 'people'];
}

/** The sheet's people and the patrons they have named, as the store holds them. */
type PeopleBody = { people: Person[]; patrons: Patron[] };

function peopleBody(sheetId: string): Promise<PeopleBody> {
  return getJson<PeopleBody>(`/api/sheets/${encodeURIComponent(sheetId)}/people`);
}

/** Read the sheet's people from the store. */
export async function fetchPeople(sheetId: string): Promise<Person[]> {
  return (await peopleBody(sheetId)).people;
}

export function patronsKey(sheetId: string) {
  return [...peopleKey(sheetId), 'patrons'];
}

/** Every patron named on the sheet, re-read from the store. */
export function usePatrons(sheetId: string) {
  return useQuery({
    queryKey: patronsKey(sheetId),
    queryFn: async () => (await peopleBody(sheetId)).patrons,
  });
}

/** The ids of those of these people who are on hold. */
export function heldIds(people: Person[] | undefined): Set<number> {
  return new Set((people ?? []).filter((p) => p.held).map((p) => p.id));
}

/** The sheet's people, in the order they were added. */
export function usePeople(sheetId: string) {
  return useQuery({
    queryKey: peopleKey(sheetId),
    queryFn: () => fetchPeople(sheetId),
  });
}
import { useState, type ChangeEvent } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { postJson } from '../../api/http';
import { useSingleFlight } from '../../query/useSingleFlight';
import { SheetBody } from '../../slots/defs/sheetBody';
import { counts, fixedDue, useClaims } from '../claims/useClaims';
import { gradeOn, heldIds, usePeople } from '../people/usePeople';
import { due, rateFor, sumDues, useRates } from '../rates/useRates';
import { dueNow } from '../overdue/useOverdue';
import { useSettings } from '../settings/useSettings';
import { useSheetToday } from '../today/useSheetToday';
import { periodOf, periodsKey, usePeriods, type Period } from './usePeriods';

/** The sheet's periods: a form that adds one (a name unique on the sheet, a from- and to-date,
 *  inclusive, overlapping no other period), and each period with its due-total: the figures of the
 *  claims that count whose date falls in it (a settled claim's frozen due, else the figure its last
 *  statement bound it to, else its live due, with its late charge while overdue), skipping those with none — fixed once it is closed —
 *  and whether it is closed, with a button that closes it. */
function Periods({ sheetId }: { sheetId: string }) {
  const periods = usePeriods(sheetId);
  const claims = useClaims(sheetId);
  const people = usePeople(sheetId);
  const rates = useRates(sheetId);
  const settings = useSettings(sheetId).data;
  const floor = settings?.floor;
  const today = useSheetToday(sheetId).data?.today;
  const queryClient = useQueryClient();
  const [name, setName] = useState('');
  const [from, setFrom] = useState('');
  const [to, setTo] = useState('');

  const submitOnce = useSingleFlight();
  const save = useMutation({
    mutationFn: (f: { name: string; from: string; to: string }) =>
      postJson<Period>(`/api/sheets/${encodeURIComponent(sheetId)}/periods`, f),
    onSuccess: async () => {
      setName('');
      setFrom('');
      setTo('');
      await queryClient.invalidateQueries({ queryKey: periodsKey(sheetId) });
    },
  });

  const field = (set: (v: string) => void) => (e: ChangeEvent<HTMLInputElement>) => {
    set(e.target.value);
    save.reset();
  };

  const dueTotal = (p: Period) => {
    if (p.closed && p.closedTotal !== null) return p.closedTotal;
    const byId = new Map((people.data ?? []).map((person) => [person.id, person]));
    const held = heldIds(people.data);
    return sumDues(
      (claims.data ?? [])
        .filter((c) => counts(c, held) && periodOf([p], c.date) !== undefined)
        .map((c) => dueNow(c, fixedDue(c) ?? due(c.amount, rateFor(rates.data, gradeOn(byId.get(c.personId), c.date), c.date), floor), settings, today)),
    );
  };

  return (
    <section data-testid="periods">
      <form
        data-testid="period-form"
        onSubmit={(e) => {
          e.preventDefault();
          submitOnce(() => {
            save.reset();
            return save.mutateAsync({ name, from, to });
          });
        }}
      >
        <label>
          Period <input data-testid="period-form-name" value={name} onChange={field(setName)} />
        </label>{' '}
        <label>
          From{' '}
          <input type="text" placeholder="yyyy-mm-dd" data-testid="period-form-from" value={from} onChange={field(setFrom)} />
        </label>{' '}
        <label>
          To <input type="text" placeholder="yyyy-mm-dd" data-testid="period-form-to" value={to} onChange={field(setTo)} />
        </label>{' '}
        <button type="submit" data-testid="period-form-submit" disabled={save.isPending}>
          Add period
        </button>
        {save.isError && <p data-testid="period-form-error">{save.error.message}</p>}
      </form>
      <table data-testid="periods-list">
        <thead>
          <tr>
            <th>Period</th>
            <th>From</th>
            <th>To</th>
            <th>Due</th>
            <th>Closed</th>
            <th />
          </tr>
        </thead>
        <tbody>
          {(periods.data ?? []).map((p) => (
            <PeriodRow key={p.id} sheetId={sheetId} period={p} dueTotal={dueTotal(p)} />
          ))}
        </tbody>
      </table>
      {periods.isError && <p data-testid="periods-error">{periods.error.message}</p>}
    </section>
  );
}

/** One period's row; closing it fixes its due-total, reopening it (a steward only) makes it live again.
 *  A refused close or reopen shows its error, cleared when the next action on the row is taken. */
function PeriodRow({ sheetId, period: p, dueTotal }: { sheetId: string; period: Period; dueTotal: string }) {
  const queryClient = useQueryClient();
  const closeOnce = useSingleFlight();
  const close = useMutation({
    mutationFn: () =>
      postJson<Period>(
        `/api/sheets/${encodeURIComponent(sheetId)}/periods/${encodeURIComponent(p.name)}/close`,
        {},
      ),
    onSuccess: async () => {
      await queryClient.invalidateQueries({ queryKey: periodsKey(sheetId) });
    },
  });
  const reopen = useMutation({
    mutationFn: () =>
      postJson<Period>(
        `/api/sheets/${encodeURIComponent(sheetId)}/periods/${encodeURIComponent(p.name)}/reopen`,
        {},
      ),
    onSuccess: async () => {
      await queryClient.invalidateQueries({ queryKey: periodsKey(sheetId) });
    },
  });
  const error = close.error ?? reopen.error;

  return (
    <tr data-testid={`period-row-${p.name}`}>
      <td data-testid="period-name">{p.name}</td>
      <td data-testid="period-from">{p.from}</td>
      <td data-testid="period-to">{p.to}</td>
      <td data-testid="period-due-total">{dueTotal}</td>
      <td data-testid="period-closed">{p.closed ? 'yes' : 'no'}</td>
      <td>
        <button
          type="button"
          data-testid="period-close"
          disabled={close.isPending}
          onClick={() =>
            closeOnce(() => {
              close.reset();
              reopen.reset();
              return close.mutateAsync();
            })
          }
        >
          Close
        </button>{' '}
        <button
          type="button"
          data-testid="period-reopen"
          disabled={reopen.isPending}
          onClick={() =>
            closeOnce(() => {
              close.reset();
              reopen.reset();
              return reopen.mutateAsync();
            })
          }
        >
          Reopen
        </button>
        {error && <span data-testid="period-error">{error.message}</span>}
      </td>
    </tr>
  );
}

export const contribution = SheetBody.fill({ order: 6, Component: ({ sheetId }) => <Periods sheetId={sheetId} /> });
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';

/** A sheet's period: its name (unique on the sheet) and its from- and to-date (yyyy-mm-dd), both
 *  inclusive, whether it is closed, and the due-total fixed when it was closed (null while open). No two
 *  periods of a sheet overlap. */
export type Period = { id: number; name: string; from: string; to: string; closed: boolean; closedTotal: string | null };

export function periodsKey(sheetId: string) {
  return ['sheet', sheetId, 'periods'];
}

/** The sheet's periods, by from-date. */
export function usePeriods(sheetId: string) {
  return useQuery({
    queryKey: periodsKey(sheetId),
    queryFn: async () =>
      (await getJson<{ periods: Period[] }>(`/api/sheets/${encodeURIComponent(sheetId)}/periods`)).periods,
  });
}

/** The period whose dates contain a date (yyyy-mm-dd); undefined when none does. */
export function periodOf(periods: Period[] | undefined, on: string): Period | undefined {
  return (periods ?? []).find((p) => p.from <= on && on <= p.to);
}
import { useState } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { postJson } from '../../api/http';
import { PersonCells, PersonColumnHead } from '../../slots/defs/personRow';
import { SheetBody } from '../../slots/defs/sheetBody';
import { peopleKey, usePeople, type Person } from '../people/usePeople';
import { useShowRetired } from './useShowRetired';

/** A person's retirement: whether they are retired and from when, and a date (blank: the sheet's
 *  today) and button that retire them. A person with a date set counts as retired at once; no claim
